const test = require('node:test');
const assert = require('node:assert/strict');
const { pluralCategory } = require('../src/plural-category.cjs');

test("omitted type uses cardinal rules", () => {
  assert.equal(pluralCategory(1), 'one');
  assert.equal(pluralCategory(2), 'other');
  assert.equal(pluralCategory(0), 'other');
  assert.equal(pluralCategory(21), 'other');
});

test("ordinal rules distinguish categories and teen endings", () => {
  assert.equal(pluralCategory(21, 'ordinal'), 'one');
  assert.equal(pluralCategory(22, 'ordinal'), 'two');
  assert.equal(pluralCategory(23, 'ordinal'), 'few');
  for (const n of [0, 4, 11, 12, 13]) assert.equal(pluralCategory(n, 'ordinal'), 'other');
  assert.equal(pluralCategory(2, 'cardinal'), 'other');
});

